import { lookup } from "node:dns/promises";
import { isIP } from "node:net";
import ipaddr from "ipaddr.js";

function normalizeHostname(hostname: string): string {
  return hostname.replace(/^\[|\]$/g, "").replace(/\.$/, "").toLowerCase();
}

export function isPrivateOrReservedAddress(rawAddress: string): boolean {
  const address = normalizeHostname(rawAddress);
  try {
    // process() normalizes IPv4-mapped IPv6 before classifying the range.
    return ipaddr.process(address).range() !== "unicast";
  } catch {
    return true;
  }
}

function configuredAllowedHosts(): Set<string> {
  return new Set(
    (process.env.ECHOES_ALLOWED_API_HOSTS ?? "")
      .split(",")
      .map((host) => normalizeHostname(host.trim()))
      .filter(Boolean),
  );
}

export interface ValidatedProviderTarget {
  url: URL;
  addresses: string[];
}

export class ProviderUrlPolicyError extends Error {
  constructor(message: string, readonly code: string) {
    super(message);
    this.name = "ProviderUrlPolicyError";
  }
}

export async function resolveProviderTarget(
  rawUrl: string,
  options: {
    allowedHosts?: Set<string>;
    allowPrivateNetwork?: boolean;
    resolve?: (hostname: string) => Promise<string[]>;
  } = {},
): Promise<ValidatedProviderTarget> {
  const url = new URL(rawUrl);
  if (!["http:", "https:"].includes(url.protocol)) {
    throw new ProviderUrlPolicyError(
      "Secondary API URL must use HTTP or HTTPS.",
      "PROVIDER_URL_PROTOCOL_INVALID",
    );
  }
  if (url.username || url.password) {
    throw new ProviderUrlPolicyError(
      "Secondary API URL must not contain embedded credentials.",
      "PROVIDER_URL_EMBEDDED_CREDENTIALS",
    );
  }

  const hostname = normalizeHostname(url.hostname);
  const allowedHosts = options.allowedHosts ?? configuredAllowedHosts();
  const trusted = allowedHosts.has(hostname) || options.allowPrivateNetwork === true;

  if (!trusted && url.protocol !== "https:") {
    throw new ProviderUrlPolicyError(
      "Non-HTTPS secondary API hosts must be explicitly listed in ECHOES_ALLOWED_API_HOSTS.",
      "PROVIDER_URL_HTTP_NOT_TRUSTED",
    );
  }
  if (!trusted && (
    hostname === "localhost"
    || hostname.endsWith(".localhost")
    || hostname.endsWith(".local")
    || hostname.endsWith(".internal")
    || hostname.endsWith(".home.arpa")
    || (isIP(hostname) !== 0 && isPrivateOrReservedAddress(hostname))
  )) {
    throw new ProviderUrlPolicyError(
      "Secondary API resolves to a private or reserved address. Enable private-network access for this endpoint only if the host is trusted.",
      "PROVIDER_URL_PRIVATE_NOT_TRUSTED",
    );
  }

  const resolve = options.resolve ?? (async (host: string) => {
    const addresses = await lookup(host, { all: true, verbatim: true });
    return addresses.map((entry) => entry.address);
  });
  const addresses = isIP(hostname) === 0 ? await resolve(hostname) : [hostname];
  if (addresses.length === 0 || (!trusted && addresses.some(isPrivateOrReservedAddress))) {
    throw new ProviderUrlPolicyError(
      "Secondary API host resolved to a private, reserved, or empty address set. Enable private-network access for this endpoint only if the host is trusted.",
      "PROVIDER_URL_PRIVATE_NOT_TRUSTED",
    );
  }
  return {
    url,
    addresses: [...new Set(addresses.map(normalizeHostname))],
  };
}

export async function validateProviderUrl(
  rawUrl: string,
  options: {
    allowedHosts?: Set<string>;
    allowPrivateNetwork?: boolean;
    resolve?: (hostname: string) => Promise<string[]>;
  } = {},
): Promise<URL> {
  return (await resolveProviderTarget(rawUrl, options)).url;
}
