import packageJson from "../../package.json";

import { API_PROTOCOL_VERSION, type BuildInfo } from "./domain";

export const ECHOES_BUILD_INFO: BuildInfo = {
  appVersion: packageJson.version,
  apiProtocolVersion: API_PROTOCOL_VERSION,
  service: "echoes-memory",
};

export function protocolCompatible(clientProtocol: number | undefined): boolean {
  return clientProtocol === undefined || clientProtocol === API_PROTOCOL_VERSION;
}
