import path from "node:path";
import type { Request } from "express";

import { JobManager } from "../jobs/job-manager";
import { RetrievalService } from "../retrieval/retrieval-service";
import { RetrievalStore } from "../retrieval/retrieval-store";
import { CredentialStore } from "./credential-store";
import { ExtractionService } from "./extraction-service";
import { GenerationService } from "./generation-service";
import { SummaryService } from "./summary-service";
import { StatusService } from "./status-service";
import { SystemService } from "./system-service";

interface SillyTavernRequestUser {
  profile?: { handle?: string };
  directories?: { root?: string };
}

export interface UserRuntime {
  handle: string;
  rootDirectory: string;
  dataDirectory: string;
  jobs: JobManager;
  credentials: CredentialStore;
  systemService: SystemService;
  subsystemErrors: Partial<Record<"jobs" | "retrieval", string>>;
  generationService: GenerationService;
  extractionService: ExtractionService;
  summaryService: SummaryService;
  statusService: StatusService;
  retrievalService: RetrievalService;
}

function requestUser(request: Request): SillyTavernRequestUser | undefined {
  return (request as Request & { user?: SillyTavernRequestUser }).user;
}

export class UserRuntimeRegistry {
  private readonly runtimes = new Map<string, Promise<UserRuntime>>();

  async forRequest(request: Request): Promise<UserRuntime> {
    const user = requestUser(request);
    const handle = user?.profile?.handle;
    const rootDirectory = user?.directories?.root;
    if (!handle || !rootDirectory) {
      throw Object.assign(new Error("Authenticated SillyTavern user context is required."), {
        statusCode: 403,
        code: "USER_CONTEXT_REQUIRED",
      });
    }

    // SillyTavern preserves a relative dataRoot such as "./data" in the
    // per-user directory map. Resolve it against the server process cwd while
    // keeping the authenticated handle and resolved root as the isolation key.
    const resolvedRootDirectory = path.resolve(rootDirectory);
    const key = `${handle}:${resolvedRootDirectory}`;
    let runtime = this.runtimes.get(key);
    if (!runtime) {
      runtime = this.createRuntime(handle, resolvedRootDirectory);
      this.runtimes.set(key, runtime);
      runtime.catch(() => this.runtimes.delete(key));
    }
    return runtime;
  }

  async prune(): Promise<void> {
    const runtimes = await Promise.allSettled(this.runtimes.values());
    await Promise.all(
      runtimes.flatMap((runtime) =>
        runtime.status === "fulfilled" ? [runtime.value.jobs.prune()] : [],
      ),
    );
  }

  async flush(): Promise<void> {
    const runtimes = await Promise.allSettled(this.runtimes.values());
    await Promise.all(
      runtimes.flatMap((runtime) =>
        runtime.status === "fulfilled" ? [runtime.value.jobs.flush()] : [],
      ),
    );
  }

  private async createRuntime(handle: string, rootDirectory: string): Promise<UserRuntime> {
    const dataDirectory = path.join(rootDirectory, "echoes-memory");
    const subsystemErrors: UserRuntime["subsystemErrors"] = {};
    const reportJobPersistenceError = (error: Error): void => {
      subsystemErrors.jobs = error.message;
    };
    let jobs = new JobManager({
      filePath: path.join(dataDirectory, "jobs.json"),
      concurrency: 1,
      onPersistenceError: reportJobPersistenceError,
    });
    try {
      await jobs.initialize();
    } catch (error) {
      subsystemErrors.jobs = error instanceof Error ? error.message : String(error);
      jobs = new JobManager({
        concurrency: 1,
        onPersistenceError: reportJobPersistenceError,
      });
      await jobs.initialize();
    }
    const credentials = new CredentialStore(dataDirectory);
    let retrievalService: RetrievalService;
    let retrievalAvailable = true;
    try {
      const retrievalStore = new RetrievalStore(path.join(dataDirectory, "retrieval"));
      await retrievalStore.initialize();
      retrievalService = new RetrievalService(retrievalStore, (endpoint) => credentials.resolve(endpoint));
    } catch (error) {
      subsystemErrors.retrieval = error instanceof Error ? error.message : String(error);
      retrievalAvailable = false;
      retrievalService = new Proxy({} as RetrievalService, {
        get() {
          throw Object.assign(new Error(subsystemErrors.retrieval ?? "Retrieval runtime is unavailable."), {
            statusCode: 503,
            code: "RETRIEVAL_UNAVAILABLE",
          });
        },
      });
    }
    const generationService = new GenerationService((endpoint) => credentials.resolve(endpoint));
    const systemService = new SystemService({
      dataDirectory,
      credentials,
      subsystemErrors,
      retrievalAvailable: () => retrievalAvailable,
      retrievalStats: () => retrievalService.listCollectionStats(),
      repairJobs: async () => {
        await jobs.attachPersistence(path.join(dataDirectory, "jobs.json"));
        delete subsystemErrors.jobs;
      },
    });
    return {
      handle,
      rootDirectory,
      dataDirectory,
      jobs,
      credentials,
      systemService,
      subsystemErrors,
      generationService,
      extractionService: new ExtractionService(generationService),
      summaryService: new SummaryService(generationService),
      statusService: new StatusService(generationService),
      retrievalService,
    };
  }
}
