import { randomUUID } from "node:crypto";
import { chmod, mkdir, readFile, rename, stat, unlink, writeFile } from "node:fs/promises";
import path from "node:path";

import type {
  CredentialMetadata,
  GenerationEndpoint,
  RetrievalEndpoint,
} from "../../shared/domain";
import { credentialMetadataSchema, identifierSchema } from "../../shared/schemas";

interface StoredCredential extends CredentialMetadata {
  secret: string;
}

interface CredentialFile {
  formatVersion: 1;
  credentials: StoredCredential[];
}

function publicMetadata(value: StoredCredential): CredentialMetadata {
  const { secret: _secret, ...metadata } = value;
  return structuredClone(metadata);
}

function credentialId(): string {
  return `credential_${randomUUID().replaceAll("-", "")}`;
}

export interface CredentialAtomicWriter {
  writeFile(
    filePath: string,
    contents: string,
    options: { encoding: "utf8"; mode: number },
  ): Promise<void>;
  rename(source: string, destination: string): Promise<void>;
  unlink(filePath: string): Promise<void>;
}

const nodeCredentialWriter: CredentialAtomicWriter = {
  writeFile,
  rename,
  unlink,
};

export async function writeCredentialFileAtomically(
  filePath: string,
  contents: string,
  writer: CredentialAtomicWriter = nodeCredentialWriter,
): Promise<void> {
  const temporary = `${filePath}.${process.pid}.${randomUUID()}.tmp`;
  try {
    await writer.writeFile(temporary, contents, { encoding: "utf8", mode: 0o600 });
    await writer.rename(temporary, filePath);
  } catch (error) {
    await writer.unlink(temporary).catch(() => undefined);
    throw error;
  }
}

export class CredentialStore {
  private readonly filePath: string;
  private writeChain: Promise<unknown> = Promise.resolve();
  private cache: CredentialFile | null = null;
  private loadPromise: Promise<CredentialFile> | null = null;
  private readonly pendingLastUsedAt = new Map<string, string>();
  private usageFlushTimer: ReturnType<typeof setTimeout> | null = null;

  constructor(
    private readonly dataDirectory: string,
    private readonly usageFlushDelayMs = 30_000,
  ) {
    this.filePath = path.join(dataDirectory, "credentials.json");
  }

  async list(): Promise<CredentialMetadata[]> {
    return (await this.read()).credentials.map(publicMetadata);
  }

  async create(input: { id?: string | undefined; name: string; secret: string }): Promise<CredentialMetadata> {
    return this.serialize(async () => {
      const file = await this.read();
      const id = identifierSchema.parse(input.id ?? credentialId());
      if (file.credentials.some((credential) => credential.id === id)) {
        throw Object.assign(new Error(`Credential already exists: ${id}`), { statusCode: 409 });
      }
      if (!input.secret || input.secret.length > 20_000) throw new Error("Credential secret is invalid.");
      const now = new Date().toISOString();
      const credential: StoredCredential = {
        id,
        name: input.name.trim(),
        secret: input.secret,
        createdAt: now,
        updatedAt: now,
      };
      credentialMetadataSchema.parse(publicMetadata(credential));
      file.credentials.push(credential);
      await this.write(file);
      return publicMetadata(credential);
    });
  }

  async createMany(
    inputs: Array<{ id?: string | undefined; name: string; secret: string }>,
  ): Promise<CredentialMetadata[]> {
    return this.serialize(async () => {
      const file = await this.read();
      const now = new Date().toISOString();
      const additions = inputs.map((input): StoredCredential => ({
        id: identifierSchema.parse(input.id ?? credentialId()),
        name: input.name.trim(),
        secret: input.secret,
        createdAt: now,
        updatedAt: now,
      }));
      const ids = [...file.credentials.map((item) => item.id), ...additions.map((item) => item.id)];
      if (new Set(ids).size !== ids.length) {
        throw Object.assign(new Error("Credential migration contains duplicate IDs."), { statusCode: 409 });
      }
      for (const credential of additions) {
        credentialMetadataSchema.parse(publicMetadata(credential));
        if (!credential.secret || credential.secret.length > 20_000) throw new Error("Credential secret is invalid.");
      }
      file.credentials.push(...additions);
      await this.write(file);
      return additions.map(publicMetadata);
    });
  }

  async update(id: string, input: { name?: string | undefined; secret?: string | undefined }): Promise<CredentialMetadata> {
    return this.serialize(async () => {
      const file = await this.read();
      const credential = file.credentials.find((item) => item.id === identifierSchema.parse(id));
      if (!credential) throw Object.assign(new Error("Credential not found."), { statusCode: 404 });
      if (input.name !== undefined) credential.name = input.name.trim();
      if (input.secret !== undefined) {
        if (!input.secret || input.secret.length > 20_000) throw new Error("Credential secret is invalid.");
        credential.secret = input.secret;
      }
      credential.updatedAt = new Date().toISOString();
      credentialMetadataSchema.parse(publicMetadata(credential));
      await this.write(file);
      return publicMetadata(credential);
    });
  }

  async delete(id: string): Promise<boolean> {
    return this.serialize(async () => {
      const file = await this.read();
      const parsedId = identifierSchema.parse(id);
      const next = file.credentials.filter((credential) => credential.id !== parsedId);
      if (next.length === file.credentials.length) return false;
      file.credentials = next;
      await this.write(file);
      return true;
    });
  }

  async resolve<T extends GenerationEndpoint | RetrievalEndpoint>(endpoint: T): Promise<T> {
    if (!endpoint.credentialId) return structuredClone(endpoint);
    const file = await this.read();
    const credential = file.credentials.find((item) => item.id === endpoint.credentialId);
    if (!credential) {
      throw Object.assign(new Error(`Credential is unavailable: ${endpoint.credentialId}`), {
        statusCode: 409,
        code: "CREDENTIAL_UNAVAILABLE",
      });
    }
    const lastUsedAt = new Date().toISOString();
    credential.lastUsedAt = lastUsedAt;
    const cached = this.cache?.credentials.find((item) => item.id === credential.id);
    if (cached) cached.lastUsedAt = lastUsedAt;
    this.pendingLastUsedAt.set(credential.id, lastUsedAt);
    this.scheduleUsageFlush();
    return { ...structuredClone(endpoint), apiKey: credential.secret };
  }

  async flushUsage(): Promise<void> {
    if (this.usageFlushTimer) {
      clearTimeout(this.usageFlushTimer);
      this.usageFlushTimer = null;
    }
    if (this.pendingLastUsedAt.size === 0) return;
    await this.serialize(async () => {
      if (this.pendingLastUsedAt.size === 0) return;
      await this.write(await this.read());
    });
  }

  async permissions(): Promise<{ exists: boolean; secure: boolean; mode?: number }> {
    try {
      const value = await stat(this.filePath);
      const mode = value.mode & 0o777;
      return { exists: true, secure: process.platform === "win32" || (mode & 0o077) === 0, mode };
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code === "ENOENT") return { exists: false, secure: true };
      throw error;
    }
  }

  async repairPermissions(): Promise<boolean> {
    const permissions = await this.permissions();
    if (!permissions.exists || process.platform === "win32") return false;
    await chmod(this.filePath, 0o600);
    return true;
  }

  private async read(): Promise<CredentialFile> {
    if (this.cache) return structuredClone(this.cache);
    this.loadPromise ??= this.readFromDisk()
      .then((file) => {
        this.cache = structuredClone(file);
        return file;
      })
      .finally(() => {
        this.loadPromise = null;
      });
    return structuredClone(await this.loadPromise);
  }

  private async readFromDisk(): Promise<CredentialFile> {
    try {
      const parsed = JSON.parse(await readFile(this.filePath, "utf8")) as Partial<CredentialFile>;
      if (parsed.formatVersion !== 1 || !Array.isArray(parsed.credentials)) {
        throw new Error("Invalid credential store format.");
      }
      return {
        formatVersion: 1,
        credentials: parsed.credentials.map((credential) => {
          const record = credential as StoredCredential;
          credentialMetadataSchema.parse(publicMetadata(record));
          if (typeof record.secret !== "string" || record.secret.length === 0) {
            throw new Error("Invalid credential secret.");
          }
          return record;
        }),
      };
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code === "ENOENT") {
        return { formatVersion: 1, credentials: [] };
      }
      throw error;
    }
  }

  private async write(file: CredentialFile): Promise<void> {
    const usageSnapshot = new Map(this.pendingLastUsedAt);
    for (const credential of file.credentials) {
      const lastUsedAt = usageSnapshot.get(credential.id);
      if (lastUsedAt) credential.lastUsedAt = lastUsedAt;
    }

    await mkdir(this.dataDirectory, { recursive: true });
    await writeCredentialFileAtomically(this.filePath, JSON.stringify(file, null, 2));
    if (process.platform !== "win32") await chmod(this.filePath, 0o600);

    for (const [id, lastUsedAt] of usageSnapshot) {
      if (this.pendingLastUsedAt.get(id) === lastUsedAt) this.pendingLastUsedAt.delete(id);
    }
    this.cache = structuredClone(file);
    for (const [id, lastUsedAt] of this.pendingLastUsedAt) {
      const credential = this.cache.credentials.find((item) => item.id === id);
      if (credential) credential.lastUsedAt = lastUsedAt;
      else this.pendingLastUsedAt.delete(id);
    }
  }

  private scheduleUsageFlush(): void {
    if (this.usageFlushTimer || this.pendingLastUsedAt.size === 0) return;
    this.usageFlushTimer = setTimeout(() => {
      this.usageFlushTimer = null;
      void this.flushUsage().catch(() => undefined);
    }, Math.max(0, this.usageFlushDelayMs));
    (this.usageFlushTimer as NodeJS.Timeout).unref?.();
  }

  private serialize<T>(operation: () => Promise<T>): Promise<T> {
    const result = this.writeChain.then(operation, operation);
    this.writeChain = result.catch(() => undefined);
    return result;
  }
}
